package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string         // PIC X len=1 = "N"
var WsC decimal.Decimal     // PIC S9(3)V99 len=5 = 0
var WsFreeze int64          // PIC 99 len=2 = 0
var WsCount int64           // PIC 99 len=2 = 0
var WsFEd string            // PIC ZZ9.9 len=5
var WsCEd string            // PIC -ZZ9.99 len=7

var tempRec TempRec

var tempFile *os.File
var scanner *bufio.Scanner

func pow10i(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

// store signed field S9(intDigits)V(decDigits) : round already done outside,
// then keep low-order integer digits (high-order truncation)
func storeSigned(val decimal.Decimal, intDigits int, decDigits int) decimal.Decimal {
	// quantize to decDigits by truncation toward zero if needed?
	// Caller already rounded for ROUNDED case. For generic we truncate.
	// To keep exact behaviour, truncate to decDigits.
	// But if val already has scale decDigits, Truncate is no-op.
	val = val.Truncate(int32(decDigits))
	if val.IsZero() {
		// preserve zero (no negative zero)
		return decimal.NewFromInt(0)
	}
	signNegative := val.Sign() < 0
	absVal := val.Abs()
	// scaled integer = absVal * 10^decDigits
	powDec := pow10i(decDigits)
	scaledDec := absVal.Mul(decimal.NewFromInt(powDec))
	// Truncate(0) to get integer part of scaled value
	scaledDec = scaledDec.Truncate(0)
	scaledInt := scaledDec.IntPart() // fits for small fields
	powDecInt64 := powDec
	intPart := scaledInt / powDecInt64
	fracPart := scaledInt % powDecInt64
	modInt := pow10i(intDigits)
	intPart = intPart % modInt
	newScaled := intPart*powDecInt64 + fracPart
	d := decimal.New(newScaled, int32(-decDigits))
	if signNegative {
		d = d.Neg()
	}
	return d
}

func formatZZ9_9(val decimal.Decimal) string {
	// PIC ZZ9.9 : intDigits=3 decDigits=1, no sign, width 5
	intDigits := 3
	decDigits := 1
	// Ensure truncation to decDigits (MOVE truncates)
	v := val.Truncate(int32(decDigits))
	absVal := v.Abs()
	// high-order truncation for edited field
	powDec := pow10i(decDigits)
	scaledDec := absVal.Mul(decimal.NewFromInt(powDec)).Truncate(0)
	scaledInt := scaledDec.IntPart()
	intPart := scaledInt / powDec
	fracPart := scaledInt % powDec
	modInt := pow10i(intDigits)
	intPart = intPart % modInt

	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	// apply Z suppression: first intDigits-1 are Z
	chars := []byte(intStr)
	// picture ZZ9 : first 2 are Z, last is 9
	for i := 0; i < intDigits-1; i++ {
		if chars[i] == '0' {
			// check if all to left are suppressed (which they are if we are in leading zero run)
			// Determine if all more significant digits are suppressed (i.e., are spaces or zeros that would be suppressed)
			// Simple rule: suppress consecutive leading zeros where picture char is Z
			allLeadingZero := true
			for k := 0; k < i; k++ {
				if chars[k] != ' ' && chars[k] != '0' {
					allLeadingZero = false
					break
				}
				// if previous was suppressed, it's space now; that's still considered leading zero zone
				// Actually need to check original chars before replacement: if any non-zero before, not leading
			}
			// Also need to check if any non-zero in earlier original positions
			// Simpler: scan from left: if we have encountered non-zero digit, stop suppression
			// We'll implement by tracking if any non-zero seen before i in original intStr
			_ = allLeadingZero
			chars[i] = ' '
			// But if later digits are not zero, we still suppress this zero
			// That's correct for ZZ9: "100" => "100" (first '1' not zero, second stays '0'? Wait second is Z but after non-zero, Z should print 0 not space)
			// So we must not suppress zeros after a non-zero has appeared.
			// So we need to detect if any non-zero digit in original intStr before or at i beyond leading zeros
		} else {
			break
		}
	}
	// The above loop with break already handles: break when non-zero found
	// But it incorrectly would leave second Z as '0' when value is 100 : intStr "100"
	// i=0 char '1' !='0' break => chars stays "100" correct.
	// For "001" (value 1): i=0 '0' -> space, i=1 '0' -> space => "  1" correct
	// For "000" (value 0): i=0 '0'->space, i=1 '0'->space => "  0" correct
	// Need to redo properly with break logic: we already break on non-zero, so zeros after non-zero are kept.
	// The preliminary check above was confused, but break logic suffices.

	// Recompute with correct simple algorithm to avoid previous messy code:
	// Regenerate
	intStr2 := fmt.Sprintf("%0*d", intDigits, intPart)
	cb := []byte(intStr2)
	for i := 0; i < intDigits-1; i++ {
		if cb[i] == '0' {
			// check if all digits to left are already suppressed (i.e., are zeros that were suppressed)
			// Actually if we are scanning left to right, and we have not yet seen a non-zero, this zero is leading
			isLeading := true
			for k := 0; k < i; k++ {
				if intStr2[k] != '0' {
					isLeading = false
					break
				}
			}
			if isLeading {
				cb[i] = ' '
			} else {
				// a non-zero was before, this zero is not leading, keep it
				break
			}
		} else {
			break
		}
	}
	// Need to also handle case where a non-zero appears early, remaining Zs that are zero should stay '0'
	// The loop above breaks on non-zero, leaving remaining chars as digits (including zeros)
	// For safety, copy cb to chars
	chars = cb

	fracStr := fmt.Sprintf("%0*d", decDigits, fracPart)
	return string(chars) + "." + fracStr
}

func formatMinusZZ9_99(val decimal.Decimal) string {
	// PIC -ZZ9.99 : sign + intDigits=3 decDigits=2 width 7
	intDigits := 3
	decDigits := 2
	// value is already stored field, but ensure truncate scale
	v := val.Truncate(int32(decDigits))
	signChar := byte(' ')
	if v.Sign() < 0 && !v.IsZero() {
		signChar = '-'
	}
	absVal := v.Abs()
	powDec := pow10i(decDigits)
	scaledDec := absVal.Mul(decimal.NewFromInt(powDec)).Truncate(0)
	scaledInt := scaledDec.IntPart()
	intPart := scaledInt / powDec
	fracPart := scaledInt % powDec
	modInt := pow10i(intDigits)
	intPart = intPart % modInt

	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	cb := []byte(intStr)
	for i := 0; i < intDigits-1; i++ {
		if cb[i] == '0' {
			isLeading := true
			for k := 0; k < i; k++ {
				if intStr[k] != '0' {
					isLeading = false
					break
				}
			}
			if isLeading {
				cb[i] = ' '
			} else {
				break
			}
		} else {
			break
		}
	}
	fracStr := fmt.Sprintf("%0*d", decDigits, fracPart)
	return string([]byte{signChar}) + string(cb) + "." + fracStr
}

func formatPic99(v int64) string {
	// PIC 99 zero padded to 2 digits, high-order truncation mod 100
	mod := pow10i(2)
	v = v % mod
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}

// helpers for reading
func parseTempRec(line string) TempRec {
	// line is already padded to 8 with spaces on right if shorter
	// ensure length at least 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	}
	if len(line) > 8 {
		line = line[:8]
	}
	sensor := line[0:4]
	rawF := line[4:8]
	// parse 9(3)V9 -> 4 digits, scale 1
	trimmed := strings.TrimSpace(rawF)
	var dec decimal.Decimal
	if trimmed == "" {
		dec = decimal.NewFromInt(0)
	} else {
		// rawF may contain spaces if padded? But we already trimmed. If rawF was "   " trimmed empty -> 0.
		// Otherwise parse digits (may contain non-digit? assume digits)
		// Need to handle if rawF has leading spaces inside digits? We'll keep only digits and sign
		// For this PIC it's unsigned, so just digits.
		// Remove any non-digit characters? Keep digits.
		digitsOnly := ""
		for _, ch := range trimmed {
			if ch >= '0' && ch <= '9' {
				digitsOnly += string(ch)
			}
		}
		if digitsOnly == "" {
			dec = decimal.NewFromInt(0)
		} else {
			// parse as integer
			var iv int64
			fmt.Sscan(digitsOnly, &iv)
			// scale 1 decimal place
			dec = decimal.New(iv, -1)
		}
	}
	return TempRec{TcSensor: sensor, TcF: dec}
}

func READ_PARA() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		// COBOL LINE SEQUENTIAL: if line shorter than record length pad with spaces
		// scanner strips newline, we handle padding in parse
		tempRec = parseTempRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	// Use decimal arithmetic
	// (TC-F -32)*5/9
	tmp := tempRec.TcF.Sub(decimal.NewFromInt(32)).Mul(decimal.NewFromInt(5)).Div(decimal.NewFromInt(9))
	// Round half away from zero to 2 decimals
	tmp = tmp.Round(2)
	WsC = storeSigned(tmp, 3, 2)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % pow10i(2)
	}
	WsCount = (WsCount + 1) % pow10i(2)
	WsFEd = formatZZ9_9(tempRec.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	fmt.Printf("%s %sF %sC\n", tempRec.TcSensor, WsFEd, WsCEd)
	READ_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT TEMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// treat as empty file
		WsEofFlag = "Y"
		scanner = nil
	} else {
		tempFile = f
		scanner = bufio.NewScanner(f)
		// Increase buffer if needed
		const maxCapacity = 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, maxCapacity)
	}
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	if tempFile != nil {
		tempFile.Close()
	}
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPic99(WsCount), formatPic99(WsFreeze))
}

func main() {
	WsEofFlag = "N"
	WsC = decimal.NewFromInt(0)
	WsFreeze = 0
	WsCount = 0
	MAIN_PARA()
}

